const db = require('better-sqlite3')('/workspace/world.db');

// Check ALL flights in the system - any route from JFK that could eventually reach SFO
// Even with 2 stops
const allFlights = db.prepare('SELECT DISTINCT origin, destination FROM flights').all();
console.log('All routes in system:');
allFlights.forEach(r => console.log(r.origin, '->', r.destination));

// BFS from JFK to SFO
const graph = {};
allFlights.forEach(r => {
  if (!graph[r.origin]) graph[r.origin] = [];
  graph[r.origin].push(r.destination);
});

// Find paths from JFK to SFO with at most 2 stops
function findPaths(start, end, maxStops) {
  const results = [];
  const queue = [[start, [start]]];
  while (queue.length > 0) {
    const [node, path] = queue.shift();
    if (path.length > maxStops + 1) continue;
    if (node === end && path.length > 1) { results.push(path); continue; }
    for (const next of (graph[node] || [])) {
      if (!path.includes(next)) queue.push([next, [...path, next]]);
    }
  }
  return results;
}

const paths = findPaths('JFK', 'SFO', 3);
console.log('\nPaths from JFK to SFO (max 3 stops):');
paths.forEach(p => console.log(p.join(' -> ')));
"

