const db = require('better-sqlite3')('/workspace/world.db');

// Sept 8 only has SFO->LAX, not helpful. Try Sept 10 which has many tau2Airline flights
// Search for one-stop JFK -> X -> SFO on 2026-09-10
const allFlights = db.prepare('SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json, cabin_prices_json FROM flights').all();

// Build flight lookup
const flightsByDate = {};
allFlights.forEach(f => {
  const dates = JSON.parse(f.dates_json || '{}');
  const prices = JSON.parse(f.cabin_prices_json || '{}');
  for (const [date, info] of Object.entries(dates)) {
    if (!flightsByDate[date]) flightsByDate[date] = [];
    flightsByDate[date].push({
      flight_id: f.flight_id,
      origin: f.origin,
      destination: f.destination,
      departure_time: f.departure_time,
      arrival_time: f.arrival_time,
      status: info.status,
      available_seats: info.available_seats,
      prices: info.prices || prices,
    });
  }
});

// Search one-stop JFK -> SFO for each available date from Sept 8 onwards
const targetDates = ['2026-09-08','2026-09-10','2026-09-12','2026-09-15'];

for (const date of targetDates) {
  const flights = flightsByDate[date] || [];
  const fromJFK = flights.filter(f => f.origin === 'JFK' && f.status === 'available');
  console.log('\\n=== ' + date + ' ===');
  console.log('Flights from JFK:', fromJFK.map(f => f.flight_id + ' ' + f.origin + '->' + f.destination + ' dep:' + f.departure_time + ' arr:' + f.arrival_time + ' status:' + f.status));

  // Check one-stop connections
  for (const leg1 of fromJFK) {
    const connectingFlights = flights.filter(f =>
      f.origin === leg1.destination &&
      f.destination === 'SFO' &&
      f.status === 'available' &&
      f.departure_time >= leg1.arrival_time
    );
    for (const leg2 of connectingFlights) {
      console.log('  FOUND: ' + leg1.flight_id + ' (' + leg1.origin + '->' + leg1.destination + ' ' + leg1.departure_time + '-' + leg1.arrival_time + ') -> ' + leg2.flight_id + ' (' + leg2.origin + '->' + leg2.destination + ' ' + leg2.departure_time + '-' + leg2.arrival_time + ')');
      console.log('    Leg1 prices:', JSON.stringify(leg1.prices), 'seats:', JSON.stringify(leg1.available_seats));
      console.log('    Leg2 prices:', JSON.stringify(leg2.prices), 'seats:', JSON.stringify(leg2.available_seats));
    }
  }
}
