const db = require('better-sqlite3')('/workspace/world.db');

// No flights from MIA to anywhere, and LHR doesn't connect to SFO
// This means there are NO one-stop JFK -> SFO routes at all in the database
// Let me verify by checking ALL possible multi-hop paths

const allFlights = db.prepare('SELECT DISTINCT origin, destination FROM flights').all();
const graph = {};
allFlights.forEach(r => {
  if (!graph[r.origin]) graph[r.origin] = new Set();
  graph[r.origin].add(r.destination);
});

console.log('Route graph:');
for (const [k, v] of Object.entries(graph)) {
  console.log(k, '->', [...v].join(', '));
}

// One-stop: JFK -> X -> SFO
console.log('\\nOne-stop JFK->SFO possibilities:');
if (graph['JFK']) {
  for (const mid of graph['JFK']) {
    if (graph[mid] && graph[mid].has('SFO')) {
      console.log('  JFK ->', mid, '-> SFO');
    }
  }
}
console.log('(end of search)');

// The nearest available date for JFK departure on/after Sep 8:
const jfkFlights = db.prepare(\"SELECT flight_id, destination, dates_json FROM flights WHERE origin = 'JFK'\").all();
console.log('\\nJFK departure dates:');
jfkFlights.forEach(f => {
  const dates = Object.keys(JSON.parse(f.dates_json || '{}'));
  const after = dates.filter(d => d >= '2026-09-08').sort();
  if (after.length) console.log(f.flight_id, 'JFK->' + f.destination, 'dates on/after Sep 8:', after);
});
"
